import { useState, useMemo, useCallback, useEffect } from 'react'
import { useAuth } from '@/contexts/AuthContext'
import { ListDetailView } from '@/components/lists/ListDetailView'
import { ListCard } from '@/components/lists/ListCard'
import { ListRow } from '@/components/lists/ListRow'
import { CollectionTable } from '@/components/shared/CollectionTable'
import { CreateListFormWrapper } from '@/components/lists/CreateListFormWrapper'
import { EditListFormWrapper } from '@/components/lists/EditListFormWrapper'
import { DeleteListDialog } from '@/components/lists/DeleteListDialog'
import { CollectionPage } from '@/components/shared/CollectionPage'
import { ViewModeSelector, type ViewMode } from '@/components/shared/ViewModeSelector'
import { Button } from '@/components/ui/button'
import { ArrowLeft, Package } from 'lucide-react'
import { useLists, useCreateList, useUpdateList, useDeleteList, useDuplicateList } from '@/hooks/useListData'
import { useGearItems } from '@/hooks/useGearData'
import type { List, WeightUnit } from '@/types/database'

export function ListsPage() {
  const { user } = useAuth()
  const [selectedList, setSelectedList] = useState<List | null>(null)
  const [searchTerm, setSearchTerm] = useState('')
  const [showCreateForm, setShowCreateForm] = useState(false)
  const [editingList, setEditingList] = useState<List | null>(null)
  const [deletingList, setDeletingList] = useState<List | null>(null)
  const weightUnit: WeightUnit = 'g' // Default weight unit for lists

  const [viewMode, setViewMode] = useState<ViewMode>(() => {
    const saved = localStorage.getItem('listsViewMode')
    // Default to comfortable (card) view on mobile for better touch experience
    const isMobile = window.innerWidth < 640
    return (saved as ViewMode) || (isMobile ? 'comfortable' : 'default')
  })

  // Data fetching
  const { data: lists = [], isLoading: listsLoading } = useLists(user?.id)
  const { data: gearItems = [], isLoading: gearLoading } = useGearItems(user?.id)

  // Mutations
  const createListMutation = useCreateList(user?.id)
  const updateListMutation = useUpdateList(user?.id)
  const deleteListMutation = useDeleteList(user?.id)
  const duplicateListMutation = useDuplicateList(user?.id)

  // Save view mode preference
  useEffect(() => {
    localStorage.setItem('listsViewMode', viewMode)
  }, [viewMode])

  const handleCreateList = useCallback(async (data: Omit<List, 'id' | 'user_id' | 'created_at' | 'updated_at'>) => {
    await createListMutation.mutateAsync(data)
    setShowCreateForm(false)
  }, [createListMutation])

  const handleEditList = useCallback(async (id: string, updates: Partial<Omit<List, 'id' | 'user_id' | 'created_at' | 'updated_at'>>) => {
    await updateListMutation.mutateAsync({ id, updates })
    setEditingList(null)
  }, [updateListMutation])

  const handleDeleteList = useCallback(async (list: List) => {
    await deleteListMutation.mutateAsync(list.id)
    setDeletingList(null)
    // If we're viewing the deleted list, go back to list view
    if (selectedList?.id === list.id) {
      setSelectedList(null)
    }
  }, [deleteListMutation, selectedList])

  const handleDuplicateList = useCallback(async (list: List) => {
    const newName = `${list.name} (Copy)`
    await duplicateListMutation.mutateAsync({ listId: list.id, newName })
  }, [duplicateListMutation])

  const handleViewList = useCallback((list: List) => {
    setSelectedList(list)
  }, [])

  const handleBackToLists = () => {
    setSelectedList(null)
  }

  // Filter lists based on search term
  const filteredLists = useMemo(() => {
    if (!searchTerm) return lists

    const searchLower = searchTerm.toLowerCase()
    return lists.filter(list =>
      list.name.toLowerCase().includes(searchLower) ||
      list.description?.toLowerCase().includes(searchLower) ||
      list.activity_type?.toLowerCase().includes(searchLower)
    )
  }, [lists, searchTerm])

  const isLoading = listsLoading || gearLoading

  const renderItems = useCallback((items: List[], currentViewMode?: string) => {
    const mode = currentViewMode || viewMode

    if (mode === 'comfortable') {
      return (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {items.map((list) => (
            <ListCard
              key={list.id}
              list={list}
              gearItems={gearItems}
              weightUnit={weightUnit}
              onView={handleViewList}
              onEdit={setEditingList}
              onDelete={setDeletingList}
              onDuplicate={handleDuplicateList}
            />
          ))}
        </div>
      )
    }

    // Default and compact views - use consistent table layout
    const columns = [
      { key: 'name', label: 'Item', sortable: false },
      { key: 'items', label: 'Items', hideOnMobile: true, className: 'text-right' },
      { key: 'weight', label: 'Weight', hideOnMobile: true, className: 'text-right' },
      { key: 'actions', label: '', className: 'text-right' }
    ]

    return (
      <CollectionTable columns={columns}>
        {items.map((list) => (
          <ListRow
            key={list.id}
            list={list}
            gearItems={gearItems}
            weightUnit={weightUnit}
            onView={handleViewList}
            onEdit={setEditingList}
            onDelete={setDeletingList}
            onDuplicate={handleDuplicateList}
          />
        ))}
      </CollectionTable>
    )
  }, [gearItems, weightUnit, handleViewList, handleDuplicateList, viewMode])

  const renderModals = useCallback(() => (
    <>
      {/* Create Form */}
      {showCreateForm && (
        <CreateListFormWrapper
          isOpen={showCreateForm}
          onCreate={handleCreateList}
          onCancel={() => setShowCreateForm(false)}
        />
      )}

      {/* Edit Form */}
      {editingList && (
        <EditListFormWrapper
          isOpen={!!editingList}
          list={editingList}
          onEdit={handleEditList}
          onCancel={() => setEditingList(null)}
        />
      )}

      {/* Delete Dialog */}
      {deletingList && (
        <DeleteListDialog
          list={deletingList}
          onConfirm={() => handleDeleteList(deletingList)}
          onCancel={() => setDeletingList(null)}
        />
      )}
    </>
  ), [showCreateForm, editingList, deletingList, handleCreateList, handleEditList, handleDeleteList])

  // Show list detail view when a list is selected
  if (selectedList) {
    return (
      <div className="min-h-screen bg-background">
        <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6 sm:py-10">
          <div className="mb-6">
            <Button
              variant="ghost"
              onClick={handleBackToLists}
              className="mb-4"
            >
              <ArrowLeft className="w-4 h-4 mr-2" />
              Back to Lists
            </Button>
          </div>

          <ListDetailView
            list={selectedList}
            gearItems={gearItems}
            onEditList={handleEditList}
            onDeleteList={(id) => handleDeleteList({ id } as List)}
            onBackToLists={handleBackToLists}
          />
        </main>
      </div>
    )
  }

  return (
    <CollectionPage<List>
      items={lists}
      filteredItems={filteredLists}
      loading={isLoading}
      title="Your Lists"
      searchTerm={searchTerm}
      onSearchChange={setSearchTerm}
      searchPlaceholder="Search lists..."
      stats={{
        itemCount: filteredLists.length,
        itemLabel: filteredLists.length !== 1 ? 'lists' : 'list'
      }}
      emptyState={{
        icon: <Package className="h-12 w-12 text-muted-foreground mx-auto mb-4" />,
        title: 'No lists found',
        description: 'Try adjusting your search term',
        noItemsTitle: 'No lists yet',
        noItemsDescription: 'Create your first list to start organizing gear for different adventures and trips.',
        showAddButton: true,
        addButtonText: 'Create Your First List'
      }}
      renderItems={renderItems}
      onAdd={() => setShowCreateForm(true)}
      renderModals={renderModals}
      showFloatingActionButton={true}
      viewMode={{
        current: viewMode,
        onChange: setViewMode,
        component: (
          <ViewModeSelector
            value={viewMode}
            onChange={setViewMode}
          />
        )
      }}
    />
  )
}

import { ReactNode } from 'react'
import {
  Table,
  TableBody,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table'
import { ChevronUp, ChevronDown, ChevronsUpDown } from 'lucide-react'

export interface TableColumn {
  key: string
  label: string
  sortable?: boolean
  className?: string
  hideOnMobile?: boolean
}

export interface CollectionTableProps {
  columns: TableColumn[]
  children: ReactNode
  sortField?: string
  sortDirection?: 'asc' | 'desc'
  onSort?: (field: string) => void
  className?: string
}

export function CollectionTable({
  columns,
  children,
  sortField,
  sortDirection,
  onSort,
  className = ''
}: CollectionTableProps) {
  const getSortIcon = (columnKey: string) => {
    if (sortField !== columnKey) {
      return <ChevronsUpDown className="ml-1 h-3 w-3 text-muted-foreground/50" />
    }
    return sortDirection === 'asc' 
      ? <ChevronUp className="ml-1 h-3 w-3" />
      : <ChevronDown className="ml-1 h-3 w-3" />
  }

  return (
    <div className={`bg-white rounded-lg border border-border/40 overflow-hidden ${className}`}>
      <Table>
        <TableHeader>
          <TableRow className="h-10">
            {columns.map((column) => (
              <TableHead
                key={column.key}
                className={`text-sm font-medium ${
                  column.sortable && onSort ? 'cursor-pointer hover:bg-accent/50' : ''
                } ${column.hideOnMobile ? 'hidden sm:table-cell' : ''} ${column.className || ''}`}
                onClick={() => column.sortable && onSort?.(column.key)}
              >
                <div className={`flex items-center ${column.className?.includes('text-right') ? 'justify-end' : ''}`}>
                  {column.label}
                  {column.sortable && onSort && getSortIcon(column.key)}
                </div>
              </TableHead>
            ))}
          </TableRow>
        </TableHeader>
        <TableBody>
          {children}
        </TableBody>
      </Table>
    </div>
  )
}

import { useState, useEffect, useMemo, useCallback } from 'react'
import { useAuth } from '@/contexts/AuthContext'
import { Package } from 'lucide-react'
import { useGearItems, useCreateGear, useUpdateGear, useDeleteGear } from '@/hooks/useGearData'
import { GearTable, type SortField, type SortDirection } from '@/components/gear/GearTable'
import { GearCard } from '@/components/gear/GearCard'
import { GearRow } from '@/components/gear/GearRow'
import { CollectionTable } from '@/components/shared/CollectionTable'
import { WeightUnitSelector } from '@/components/gear/WeightUnitSelector'
import { EditGearForm } from '@/components/gear/EditGearForm'
import { DeleteDialog } from '@/components/gear/DeleteDialog'
import { AddGearFormWrapper } from '@/components/gear/AddGearFormWrapper'
import { CollectionPage } from '@/components/shared/CollectionPage'
import { ViewModeSelector, type ViewMode } from '@/components/shared/ViewModeSelector'
import type { GearItem, WeightUnit } from '@/types/database'
import { formatWeightWithUnit } from '@/utils/weight'

export function GearPage() {
  const { user } = useAuth()

  // Use React Query hooks for data fetching and mutations
  const { data: items = [], isLoading: loading } = useGearItems(user?.id)
  const createGearMutation = useCreateGear(user?.id)
  const updateGearMutation = useUpdateGear(user?.id)
  const deleteGearMutation = useDeleteGear(user?.id)

  const [viewMode, setViewMode] = useState<ViewMode>(() => {
    const saved = localStorage.getItem('gearViewMode')
    // Default to comfortable (card) view on mobile for better touch experience
    const isMobile = window.innerWidth < 640
    return (saved as ViewMode) || (isMobile ? 'comfortable' : 'default')
  })
  const [weightUnit, setWeightUnit] = useState<WeightUnit>(() => {
    const saved = localStorage.getItem('gearWeightUnit')
    return (saved as WeightUnit) || 'g'
  })
  const [searchTerm, setSearchTerm] = useState('')
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null)
  const [showAddForm, setShowAddForm] = useState(false)
  const [editingItem, setEditingItem] = useState<GearItem | null>(null)
  const [deletingItem, setDeletingItem] = useState<GearItem | null>(null)
  const [sortField, setSortField] = useState<SortField>('name')
  const [sortDirection, setSortDirection] = useState<SortDirection>('asc')


  // Save view mode preference
  useEffect(() => {
    localStorage.setItem('gearViewMode', viewMode)
  }, [viewMode])

  // Save weight unit preference
  useEffect(() => {
    localStorage.setItem('gearWeightUnit', weightUnit)
  }, [weightUnit])

  // Filter items based on search and category with memoization
  const filteredItems = useMemo(() => {
    let filtered = items

    if (searchTerm) {
      const searchLower = searchTerm.toLowerCase()
      filtered = filtered.filter(item =>
        item.name.toLowerCase().includes(searchLower) ||
        item.brand?.toLowerCase().includes(searchLower) ||
        item.model?.toLowerCase().includes(searchLower) ||
        item.category.toLowerCase().includes(searchLower) ||
        item.notes?.toLowerCase().includes(searchLower) ||
        item.description?.toLowerCase().includes(searchLower)
      )
    }

    if (selectedCategory) {
      filtered = filtered.filter(item => item.category === selectedCategory)
    }

    return filtered
  }, [items, searchTerm, selectedCategory])

  // Sort filtered items with memoization
  const sortedItems = useMemo(() => {
    const sorted = [...filteredItems].sort((a, b) => {
      let aValue: string | number = a[sortField as keyof GearItem] as string | number
      let bValue: string | number = b[sortField as keyof GearItem] as string | number

      // Handle 'total' which is calculated
      if (sortField === 'total') {
        aValue = a.weight_grams * a.quantity
        bValue = b.weight_grams * b.quantity
      }

      // Handle null/undefined values
      if (aValue == null && bValue == null) return 0
      if (aValue == null) return sortDirection === 'asc' ? 1 : -1
      if (bValue == null) return sortDirection === 'asc' ? -1 : 1

      // Handle string comparison
      if (typeof aValue === 'string' && typeof bValue === 'string') {
        return sortDirection === 'asc'
          ? aValue.localeCompare(bValue)
          : bValue.localeCompare(aValue)
      }

      // Handle number comparison
