-- Rename trip_lists table to lists
-- This migration safely renames the table and updates all related objects

BEGIN;

-- Rename the table
ALTER TABLE trip_lists RENAME TO lists;

-- Update indexes (they should automatically rename with the table)
-- But let's be explicit for clarity
DROP INDEX IF EXISTS idx_trip_lists_user_id;
CREATE INDEX idx_lists_user_id ON lists(user_id);

-- Update the trigger (drop old, create new)
DROP TRIGGER IF EXISTS update_trip_lists_updated_at ON lists;
CREATE TRIGGER update_lists_updated_at BEFORE UPDATE ON lists
  FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

-- RLS Policies are automatically updated with the table name change
-- But let's verify they exist with correct names
DROP POLICY IF EXISTS "Users can view own lists" ON lists;
DROP POLICY IF EXISTS "Users can insert own lists" ON lists;
DROP POLICY IF EXISTS "Users can update own lists" ON lists;
DROP POLICY IF EXISTS "Users can delete own lists" ON lists;

-- Recreate RLS policies with clean names
CREATE POLICY "Users can view own lists" ON lists
  FOR SELECT USING (auth.uid() = user_id);

CREATE POLICY "Users can insert own lists" ON lists
  FOR INSERT WITH CHECK (auth.uid() = user_id);

CREATE POLICY "Users can update own lists" ON lists
  FOR UPDATE USING (auth.uid() = user_id);

CREATE POLICY "Users can delete own lists" ON lists
  FOR DELETE USING (auth.uid() = user_id);

COMMIT;

-- BetterPack Initial Schema
-- Simple, working schema for MVP

-- Enable UUID extension
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

-- Gear items table
CREATE TABLE gear_items (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  weight_grams INTEGER NOT NULL,
  category TEXT DEFAULT 'Other',
  quantity INTEGER DEFAULT 1,
  worn BOOLEAN DEFAULT FALSE,
  consumable BOOLEAN DEFAULT FALSE,
  notes TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Trip lists table
CREATE TABLE trip_lists (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  gear_ids TEXT[], -- Just an array of IDs for now, normalize later if needed
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Enable Row Level Security
ALTER TABLE gear_items ENABLE ROW LEVEL SECURITY;
ALTER TABLE trip_lists ENABLE ROW LEVEL SECURITY;

-- RLS Policies for gear_items
CREATE POLICY "Users can view own gear" ON gear_items
  FOR SELECT USING (auth.uid() = user_id);

CREATE POLICY "Users can insert own gear" ON gear_items
  FOR INSERT WITH CHECK (auth.uid() = user_id);

CREATE POLICY "Users can update own gear" ON gear_items
  FOR UPDATE USING (auth.uid() = user_id);

CREATE POLICY "Users can delete own gear" ON gear_items
  FOR DELETE USING (auth.uid() = user_id);

-- RLS Policies for trip_lists
CREATE POLICY "Users can view own lists" ON trip_lists
  FOR SELECT USING (auth.uid() = user_id);

CREATE POLICY "Users can insert own lists" ON trip_lists
  FOR INSERT WITH CHECK (auth.uid() = user_id);

CREATE POLICY "Users can update own lists" ON trip_lists
  FOR UPDATE USING (auth.uid() = user_id);

CREATE POLICY "Users can delete own lists" ON trip_lists
  FOR DELETE USING (auth.uid() = user_id);

-- Indexes for performance
CREATE INDEX idx_gear_items_user_id ON gear_items(user_id);
CREATE INDEX idx_trip_lists_user_id ON trip_lists(user_id);

-- Updated at trigger function
CREATE OR REPLACE FUNCTION update_updated_at_column()
RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$ language 'plpgsql';

-- Add triggers for updated_at
CREATE TRIGGER update_gear_items_updated_at BEFORE UPDATE ON gear_items
  FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

CREATE TRIGGER update_trip_lists_updated_at BEFORE UPDATE ON trip_lists
  FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

