import { CollectionRow, type RowAction, type RowBadge } from '@/components/shared/CollectionRow'
import { Edit2, Trash2, Copy, Eye } from 'lucide-react'
import type { List, GearItem, WeightUnit } from '@/types/database'
import { formatWeightWithUnit } from '@/utils/weight'

interface ListRowProps {
  list: List
  gearItems: GearItem[]
  weightUnit: WeightUnit
  onView: (list: List) => void
  onEdit: (list: List) => void
  onDelete: (list: List) => void
  onDuplicate: (list: List) => void
}

export function ListRow({ 
  list, 
  gearItems,
  weightUnit,
  onView,
  onEdit, 
  onDelete,
  onDuplicate
}: ListRowProps) {
  // Calculate list stats
  const listGear = gearItems.filter(item => list.gear_ids.includes(item.id))
  const totalWeight = listGear.reduce((sum, item) => sum + (item.weight_grams * item.quantity), 0)

  // No category column for lists (activity type will show in mobile metadata only)

  // Build metadata for mobile
  const itemCount = list.gear_ids.length
  const itemText = itemCount === 1 ? 'item' : 'items'
  const weightDisplay = totalWeight > 0 
    ? formatWeightWithUnit(totalWeight, weightUnit)
    : '0g'

  // Include activity type in mobile metadata if present
  const metadataParts = [
    `${itemCount} ${itemText}`,
    ...(list.activity_type ? [list.activity_type] : []),
    weightDisplay
  ]
  const metadata = metadataParts.join(' • ')

  // For lists, show item count and weight in secondary columns (no activity column)
  const secondaryInfo = [
    itemCount,
    weightDisplay
  ]

  const columnClasses = ['text-right', 'text-right font-medium']

  // Build actions
  const actions: RowAction[] = [
    {
      label: 'View',
      icon: <Eye className="h-4 w-4" />,
      onClick: () => onView(list)
    },
    {
      label: 'Edit',
      icon: <Edit2 className="h-4 w-4" />,
      onClick: () => onEdit(list)
    },
    {
      label: 'Duplicate',
      icon: <Copy className="h-4 w-4" />,
      onClick: () => onDuplicate(list)
    },
    {
      label: 'Delete',
      icon: <Trash2 className="h-4 w-4" />,
      onClick: () => onDelete(list),
      variant: 'destructive',
      separator: true
    }
  ]

  return (
    <CollectionRow
      title={list.name}
      subtitle={list.description}
      metadata={metadata}
      secondaryInfo={secondaryInfo}
      columnClasses={columnClasses}
      actions={actions}
      onClick={() => onView(list)}
    />
  )
}

